"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["34034"],{72829(e){e.exports=JSON.parse('{"id":"FIN-287","slug":"private-company","term":"Private Company","also_known_as":[],"difficulty":"Intermediate","definition":"A private company is a company whose shares are not traded publicly and are usually owned by a small group, such as founders, families, employees or private investors.","explanation":["Most companies in the world are private, from small family businesses to some very large international firms. Their shares cannot be bought on a stock exchange, and ownership changes only through private sales.","Private companies have fewer reporting obligations than public companies. In many countries, they still file basic accounts, but they do not have to publish detailed quarterly results or meet stock exchange rules. This allows them to keep more information confidential and to focus on long-term goals without pressure from public investors.","The main disadvantage is access to capital. Private companies cannot easily raise money from the public, so they rely on bank loans, the owners\' own money, profits and private investors such as venture capital or private equity funds. It is also harder for owners to sell their shares, because there is no public market.","Many companies start private and later go public through an initial public offering. Public companies can also become private again, for example when bought by a private equity firm."],"note":"","total":1500,"prev":{"slug":"private-banking","term":"Private Banking"},"next":{"slug":"private-equity","term":"Private Equity"}}')}}]);